/**
 * Tests for deployed MCP OAuth secret materialization.
 *
 * Ports tests/unit/test_mcp_oauth_secret.py — verifies AGENTIC_MCP_OAUTH_B64_*
 * env secrets decode into the file cache with the same layout the reader
 * (mcp_oauth.ts) and the Go CLI expect.
 */

import { test, expect, beforeEach, afterEach } from "vitest";
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  statSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
  RuntimeMCPServerConfigSchema,
  makeMcpOauthAuth,
  materializeMcpOauthSecretCache,
  mcpOauthCacheName,
} from "../../src/index.js";

let cacheDir: string;
const savedEnv: Record<string, string | undefined> = {};

function trackEnv(...names: string[]): void {
  for (const name of names) savedEnv[name] = process.env[name];
}

beforeEach(() => {
  // A parent dir; tests point defaultCacheDir at a not-yet-created child so
  // mkdir behavior is exercised (matching the Python tmp_path/"cache" pattern).
  cacheDir = join(mkdtempSync(join(tmpdir(), "mcp-oauth-secret-")), "cache");
  trackEnv("AGENTIC_MCP_OAUTH_DIR");
  delete process.env["AGENTIC_MCP_OAUTH_DIR"];
});

afterEach(() => {
  rmSync(cacheDir, { recursive: true, force: true });
  for (const [name, value] of Object.entries(savedEnv)) {
    if (value === undefined) delete process.env[name];
    else process.env[name] = value;
    delete savedEnv[name];
  }
});

function b64(value: string): string {
  return Buffer.from(value, "utf-8").toString("base64");
}

test("sets the runtime cache dir without any secret", async () => {
  const materialized = await materializeMcpOauthSecretCache({
    defaultCacheDir: cacheDir,
  });

  expect(materialized).toBe(0);
  expect(process.env["AGENTIC_MCP_OAUTH_DIR"]).toBe(cacheDir);
  expect(statSync(cacheDir).isDirectory()).toBe(true);
});

test("writes the decoded cache file using the payload server_name", async () => {
  const payload = {
    schema_version: 1,
    server_name: "github-enterprise-team",
    server_url: "https://github.example.com/mcp/",
    tokens: { access_token: "[REDACTED]", refresh_token: "[REDACTED]" },
  };
  const raw = JSON.stringify(payload, null, 2);
  const envName = "AGENTIC_MCP_OAUTH_B64_GITHUB_ENTERPRISE_TEAM";
  trackEnv(envName);
  process.env[envName] = b64(raw);

  const materialized = await materializeMcpOauthSecretCache({
    defaultCacheDir: cacheDir,
  });

  const cacheFile = join(
    cacheDir,
    `${mcpOauthCacheName(payload.server_name, payload.server_url)}.json`,
  );
  expect(materialized).toBe(1);
  expect(process.env["AGENTIC_MCP_OAUTH_DIR"]).toBe(cacheDir);
  expect(readFileSync(cacheFile, "utf-8")).toBe(raw);
  expect(statSync(cacheFile).mode & 0o777).toBe(0o600);
  // Consumed env var is removed so it can't leak downstream.
  expect(process.env[envName]).toBeUndefined();
});

test("falls back to the env suffix as the cache name", async () => {
  const payload = {
    server_url: "https://github.example.com/mcp/",
    tokens: { refresh_token: "[REDACTED]" },
  };
  const raw = JSON.stringify(payload);
  const envName = "AGENTIC_MCP_OAUTH_B64_GITHUB_ENTERPRISE";
  trackEnv(envName);
  process.env[envName] = b64(raw);

  const materialized = await materializeMcpOauthSecretCache({
    defaultCacheDir: cacheDir,
  });

  expect(materialized).toBe(1);
  expect(
    readFileSync(
      join(
        cacheDir,
        `${mcpOauthCacheName("github_enterprise", payload.server_url)}.json`,
      ),
      "utf-8",
    ),
  ).toBe(raw);
});

test("reader resolves the same cache dir the writer set (barrel import)", async () => {
  // Regression guard: the reader's cache dir must be resolved at call time,
  // not frozen when mcp_oauth.ts is first imported. Importing everything from
  // the package barrel (as here) loads mcp_oauth.ts before materialize runs;
  // a frozen dir would leave the reader looking in the wrong place.
  const serverUrl = "https://mcp.example.com/github";
  const payload = {
    server_name: "github",
    server_url: serverUrl,
    tokens: { access_token: "[REDACTED]" },
  };
  const envName = "AGENTIC_MCP_OAUTH_B64_GITHUB";
  trackEnv(envName);
  process.env[envName] = b64(JSON.stringify(payload));

  await materializeMcpOauthSecretCache({ defaultCacheDir: cacheDir });

  // No explicit cacheDir — the provider must pick up AGENTIC_MCP_OAUTH_DIR
  // that materialize just set.
  const config = RuntimeMCPServerConfigSchema.parse({
    url: serverUrl,
    auth: { type: "oauth" },
  });
  const provider = makeMcpOauthAuth("github", config);
  expect((await provider.tokens())?.access_token).toBe("access-token");
});

test("rejects an invalid secret without leaking its value", async () => {
  const envName = "AGENTIC_MCP_OAUTH_B64_GITHUB";
  trackEnv(envName);
  process.env[envName] = "not base64!!!";

  let thrown: Error | undefined;
  try {
    await materializeMcpOauthSecretCache({ defaultCacheDir: cacheDir });
  } catch (e) {
    thrown = e as Error;
  }

  expect(thrown).toBeInstanceOf(Error);
  expect(thrown?.message).toContain(envName);
  expect(thrown?.message).not.toContain("not base64");
  expect(existsSync(join(cacheDir, "github.json"))).toBe(false);
});

test("preserves a legacy payload server name identity", async () => {
  // A payload minted before any naming rule can carry an arbitrary alias; the
  // materialized file must land exactly where the runtime reader for that
  // same alias looks.
  const payload = {
    server_name: "GitHub Enterprise",
    server_url: "https://github.example.com/mcp/",
    tokens: { refresh_token: "token" },
  };
  const envName = "AGENTIC_MCP_OAUTH_B64_GITHUB_ENTERPRISE";
  trackEnv(envName);
  process.env[envName] = b64(JSON.stringify(payload));

  await materializeMcpOauthSecretCache({ defaultCacheDir: cacheDir });

  expect(
    readFileSync(
      join(
        cacheDir,
        `${mcpOauthCacheName(payload.server_name, payload.server_url)}.json`,
      ),
      "utf-8",
    ),
  ).toBe(JSON.stringify(payload));
});

/**
 * Tests for MCP OAuth providers and file-backed token caching.
 *
 * Mirrors the file-cache-format coverage in Python's tests/unit/test_mcp_oauth.py.
 * Adapted to `@modelcontextprotocol/sdk`'s `OAuthClientProvider` interface —
 * see the `mcp_oauth.ts` module comment for why this isn't a literal port.
 */

import { describe, test, expect, beforeEach, afterEach, vi } from "vitest";
import {
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  statSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
  RuntimeMCPServerConfigSchema,
  makeMcpClientCredentialsAuth,
  makeMcpOauthAuth,
  mcpOauthCacheName,
} from "../../src/index.js";

let cacheDir: string;

beforeEach(() => {
  cacheDir = mkdtempSync(join(tmpdir(), "mcp-oauth-"));
});

afterEach(() => {
  rmSync(cacheDir, { recursive: true, force: true });
  vi.unstubAllEnvs();
});

function makeServerConfig(overrides: Record<string, unknown> = {}) {
  return RuntimeMCPServerConfigSchema.parse({
    url: "https://mcp.example.com/github",
    ...overrides,
  });
}

describe("mcpOauthCacheName", () => {
  // Mirrored by the Go (mcpname) and Python parity tests; a drift in any
  // implementation breaks the shared cache layout.
  const url = "https://mcp.example.com/one";
  const urlHash =
    "34fcf0941fd4db94f72e35ac8d58114ce17a82c9949c883fa6f2767b5c095c2b";

  test.each([
    ["github", `github-${urlHash}`],
    ["github_enterprise", `github_enterprise-${urlHash}`],
    ["GitHub", `GitHub-${urlHash}`],
    ["github.com", `github-com-3aeb002460381c6f-${urlHash}`],
    ["github com", `github-com-7950713f209fb3ca-${urlHash}`],
    [" /// ", `663b6e4b48f7158c-${urlHash}`],
    [
      "GitHub Enterprise / Team",
      `GitHub-Enterprise-Team-5616f7fc218b4465-${urlHash}`,
    ],
    ["a".repeat(65), `${"a".repeat(40)}-635361c48bb9eab1-${urlHash}`],
  ])("derives %s as %s", (serverName, expected) => {
    expect(mcpOauthCacheName(serverName, url)).toBe(expected);
  });

  test("separates aliases that sanitize to the same readable form", () => {
    expect(mcpOauthCacheName("github.com", url)).not.toBe(
      mcpOauthCacheName("github com", url),
    );
    expect(mcpOauthCacheName("github.com", url)).not.toBe(
      mcpOauthCacheName("github/com", url),
    );
  });
});

describe("makeMcpOauthAuth", () => {
  test("isolates the same alias at different server URLs", async () => {
    const first = makeMcpOauthAuth(
      "github",
      makeServerConfig({
        url: "https://mcp.example.com/one",
        auth: { type: "oauth" },
      }),
      cacheDir,
    );
    const second = makeMcpOauthAuth(
      "github",
      makeServerConfig({
        url: "https://mcp.example.com/two",
        auth: { type: "oauth" },
      }),
      cacheDir,
    );

    await first.saveTokens({ access_token: "first" });
    await second.saveTokens({ access_token: "second" });

    expect(readdirSync(cacheDir).sort()).toHaveLength(2);
    expect(readdirSync(cacheDir)).toEqual(
      expect.arrayContaining([
        "github-34fcf0941fd4db94f72e35ac8d58114ce17a82c9949c883fa6f2767b5c095c2b.json",
      ]),
    );
  });

  test("has no cached tokens before any login", async () => {
    const config = makeServerConfig({ auth: { type: "oauth" } });
    const provider = makeMcpOauthAuth("github", config, cacheDir);
    expect(await provider.tokens()).toBeUndefined();
  });

  test("reads tokens back after saveTokens (same cache file the CLI writes)", async () => {
    const config = makeServerConfig({ auth: { type: "oauth" } });
    const provider = makeMcpOauthAuth("github", config, cacheDir);

    await provider.saveTokens({
      access_token: "abc123",
      token_type: "Bearer",
      refresh_token: "refresh-abc",
      expires_in: 3600,
    });

    const tokens = await provider.tokens();
    expect(tokens).toMatchObject({
      access_token: "abc123",
      token_type: "Bearer",
      refresh_token: "refresh-abc",
    });
    expect(tokens?.expires_in).toBeGreaterThan(3500);

    const cachePath = join(
      cacheDir,
      `${mcpOauthCacheName("github", config.url)}.json`,
    );
    expect(statSync(cachePath).mode & 0o777).toBe(0o600);
    const onDisk = JSON.parse(readFileSync(cachePath, "utf-8"));
    expect(onDisk.server_url).toBe("https://mcp.example.com/github");
    expect(onDisk.tokens.access_token).toBe("abc123");
    expect(onDisk.tokens.expiry).toBeDefined();
    expect(onDisk.tokens.expires_in).toBeUndefined();
  });

  test("concurrent saveTokens + saveClientInformation don't clobber each other (lock covers the read-modify-write)", async () => {
    // Without the advisory lock around writePayload()'s read-modify-write,
    // two concurrent writers can each read the same (stale) payload and
    // write back only their own key, silently losing whichever finished
    // first — a lost-update race. Running both concurrently here proves the
    // lock serializes them so both keys survive.
    const config = makeServerConfig({ auth: { type: "oauth" } });
    const provider = makeMcpOauthAuth("github", config, cacheDir);

    await Promise.all([
      provider.saveTokens({ access_token: "token-a", token_type: "Bearer" }),
      Promise.resolve(
        provider.saveClientInformation?.({
          redirect_uris: ["http://127.0.0.1:8765/callback"],
          client_id: "client-xyz",
          grant_types: ["authorization_code", "refresh_token"],
          response_types: ["code"],
        }),
      ),
    ]);

    const cachePath = join(
      cacheDir,
      `${mcpOauthCacheName("github", config.url)}.json`,
    );
    const onDisk = JSON.parse(readFileSync(cachePath, "utf-8"));
    expect(onDisk.tokens?.access_token).toBe("token-a");
    expect(onDisk.client?.client_id).toBe("client-xyz");
  });

  test("returns undefined when the cached server_url does not match (e.g. url changed)", async () => {
    const config = makeServerConfig({ auth: { type: "oauth" } });
    const provider = makeMcpOauthAuth("github", config, cacheDir);
    await provider.saveTokens({ access_token: "abc123", token_type: "Bearer" });

    const otherConfig = makeServerConfig({
      url: "https://mcp.example.com/other-github",
      auth: { type: "oauth" },
    });
    const otherProvider = makeMcpOauthAuth("github", otherConfig, cacheDir);
    expect(await otherProvider.tokens()).toBeUndefined();
  });

  test("redirectToAuthorization/codeVerifier require the CLI login flow", async () => {
    const config = makeServerConfig({ auth: { type: "oauth" } });
    const provider = makeMcpOauthAuth("github", config, cacheDir);

    expect(() =>
      provider.redirectToAuthorization(new URL("https://x")),
    ).toThrow(/agentengine dev mcp auth login github/);
    expect(() => provider.codeVerifier()).toThrow(
      /agentengine dev mcp auth login github/,
    );
  });

  test("clientMetadata reflects configured client_name/scope/redirect_uri", () => {
    const config = makeServerConfig({
      auth: {
        type: "oauth",
        client_name: "My Agent",
        scope: "repo read:org",
        redirect_uri: "http://127.0.0.1:9999/callback",
      },
    });
    const provider = makeMcpOauthAuth("github", config, cacheDir);
    expect(provider.clientMetadata).toMatchObject({
      client_name: "My Agent",
      scope: "repo read:org",
      redirect_uris: ["http://127.0.0.1:9999/callback"],
      token_endpoint_auth_method: "none",
    });
    expect(provider.redirectUrl).toBe("http://127.0.0.1:9999/callback");
  });
});

